import json
import os


def read_role_file(role_path):
    """Load a role metadata file with the stdlib json module (new code)."""
    with open(os.fspath(role_path), "rb") as file:
        return json.loads(file.read().decode("utf-8"))


def write_role_file(role_path, signed_dict):
    """Store a role metadata file with the stdlib json module (new code)."""
    with open(os.fspath(role_path), "wb") as file:
        file.write(json.dumps(signed_dict).encode("utf-8"))


